47	interface PricingRow {
48	  code?: string;
49	  currency?: string | null;
50	  numberLocale?: string | null;
51	  driverAgeBands?: unknown[] | null;
52	  vehicleAgeBands?: unknown[] | null;
53	}
54	
55	/** Pure: the values a country is missing, taken from the defaults. Present values are never in the patch. */
56	export function pricingPatch(row: PricingRow): Record<string, unknown> {
57	  const defaults = PRICING_DEFAULTS[row.code ?? ''];
58	  const patch: Record<string, unknown> = {};
59	  if (!row.currency && defaults) patch.currency = defaults.currency;
60	  if (!row.numberLocale && defaults) patch.numberLocale = defaults.numberLocale;
61	  if (!row.driverAgeBands?.length) patch.driverAgeBands = DRIVER_BANDS;
62	  if (!row.vehicleAgeBands?.length) patch.vehicleAgeBands = VEHICLE_BANDS;
63	  return patch;
64	}
