66	/** Existing databases get currency, locale and bands only where they are missing (US-02). */
67	export async function backfillCountryPricing(strapi: Core.Strapi): Promise<void> {
68	  for (const status of ['draft', 'published'] as const) {
69	    const rows = (await strapi.documents(UID).findMany({
70	      status,
71	      populate: { driverAgeBands: true, vehicleAgeBands: true },
72	    })) as unknown as Array<PricingRow & { documentId: string }>;
73	    for (const row of rows) {
74	      const patch = pricingPatch(row);
75	      if (Object.keys(patch).length === 0) continue;
76	      await strapi.documents(UID).update({ documentId: row.documentId, data: patch as never, status });
77	    }
78	  }
79	}
