81	async function uploadIcon(strapi: Core.Strapi, file: string, alt: string): Promise<number> {
82	  // Read from src/ (not dist/) so the SVGs do not need a build copy step.
83	  const filepath = path.join(strapi.dirs.app.root, 'src', 'seed', 'assets', file);
84	  const { size } = fs.statSync(filepath);
85	  const [uploaded] = await strapi.plugin('upload').service('upload').upload({
86	    data: { fileInfo: { name: file, alternativeText: alt, caption: alt } },
87	    files: { filepath, originalFilename: file, mimetype: 'image/svg+xml', size },
88	  });
89	  return uploaded.id;
90	}
