92	export async function seedCountries(strapi: Core.Strapi): Promise<void> {
93	  const total = await strapi.documents(UID).count({});
94	  if (total > 0) return;
95	
96	  for (const country of COUNTRIES) {
97	    const icon = country.icon ? await uploadIcon(strapi, country.icon.file, country.icon.alt) : undefined;
98	    await strapi.documents(UID).create({
99	      data: { code: country.code, name: country.name, order: country.order, active: country.active, legalAge: country.legalAge, currency: country.currency, numberLocale: country.numberLocale, driverAgeBands: DRIVER_BANDS, vehicleAgeBands: VEHICLE_BANDS, icon },
100	      status: 'published',
101	    });
102	  }
103	}
