1	import type { Core } from '@strapi/strapi';
2	import { errors } from '@strapi/utils';
3	
4	const UID = 'api::form-field.form-field';
5	const PLAN_UID = 'api::plan.plan';
6	const ACTIONS = ['create', 'update', 'publish'];
7	
8	export interface FormFieldIntegrityInput {
9	  key?: string | null;
10	  countryDocumentId?: string | null;
11	  selfDocumentId?: string | null;
12	}
13	
14	export interface ExistingKey {
15	  documentId: string;
16	  key: string;
17	}
18	
19	/** Pure rule: a field needs a country, and its key is unique within that country. */
20	export function checkFormFieldIntegrity(
21	  input: FormFieldIntegrityInput,
22	  existingSameCountryKeys: ExistingKey[],
23	): string | null {
24	  if (!input.countryDocumentId) return 'El campo debe tener un país.';
25	  const duplicate = existingSameCountryKeys.some(
26	    (f) => f.key === input.key && f.documentId !== input.selfDocumentId,
27	  );
28	  if (duplicate) return `Ya existe un campo con la clave «${input.key}» para este país.`;
29	  return null;
30	}
31	
32	/** Pure rule: a plan needs a country, otherwise it silently disappears from every country's list. */
33	export function checkPlanIntegrity(input: { countryDocumentId?: string | null }): string | null {
34	  if (!input.countryDocumentId) return 'El plan debe tener un país.';
35	  return null;
36	}
37	
38	type Ref = string | number;
39	
40	function refOf(item: unknown): Ref | null {
41	  if (typeof item === 'string' || typeof item === 'number') return item;
42	  if (item && typeof item === 'object') {
43	    const o = item as Record<string, unknown>;
44	    return (o.documentId ?? o.id ?? null) as Ref | null;
45	  }
46	  return null;
47	}
48	
49	/** Reads the country from the relation payload shapes Strapi accepts. `present=false` means untouched. */
50	export function readCountryPayload(value: unknown): { present: boolean; ref: Ref | null } {
51	  if (value === undefined) return { present: false, ref: null };
52	  if (value === null) return { present: true, ref: null };
53	  if (typeof value === 'string' || typeof value === 'number') return { present: true, ref: value };
54	  if (typeof value === 'object') {
55	    const v = value as Record<string, unknown>;
56	    // `set` replaces the relation: an empty set clears it.
57	    if (Array.isArray(v.set)) return { present: true, ref: refOf(v.set[0]) };
58	    if (Array.isArray(v.connect) && v.connect.length > 0) return { present: true, ref: refOf(v.connect[0]) };
59	    if (Array.isArray(v.disconnect) && v.disconnect.length > 0) return { present: true, ref: null };
60	    // The admin sends `{ connect: [], disconnect: [] }` when the relation is left as is.
61	    if (Array.isArray(v.connect) || Array.isArray(v.disconnect)) return { present: false, ref: null };
62	    if (v.documentId !== undefined || v.id !== undefined) return { present: true, ref: refOf(v) };
63	  }
64	  return { present: false, ref: null };
65	}
66	
67	export function registerCountryIntegrity(strapi: Core.Strapi): void {
68	  strapi.documents.use(async (context, next) => {
69	    if (!ACTIONS.includes(context.action)) return next();
70	    if (context.uid === PLAN_UID) return checkPlan(strapi, context, next);
71	    if (context.uid !== UID) return next();
72	
73	    const params = (context.params ?? {}) as { documentId?: string; data?: Record<string, unknown> };
74	    const data = params.data ?? {};
75	    const selfDocumentId = params.documentId ?? null;
76	
77	    type Existing = { key?: string; country?: { documentId: string } | null } | null;
78	    let existing = null as Existing;
79	    if (selfDocumentId) {
80	      existing = (await strapi.documents(UID).findOne({
81	        documentId: selfDocumentId,
82	        populate: { country: { fields: ['documentId'] } },
83	        status: 'draft',
84	      })) as Existing;
85	    }
86	
87	    const key = (data.key as string | undefined) ?? existing?.key ?? null;
88	
89	    const { present, ref } = readCountryPayload(data.country);
90	    let countryDocumentId: string | null = null;
91	    if (present) {
92	      if (typeof ref === 'number') {
93	        const found = (await strapi.db.query('api::country.country').findOne({ where: { id: ref } })) as {
94	          documentId: string;
95	        } | null;
96	        countryDocumentId = found?.documentId ?? null;
97	      } else {
98	        countryDocumentId = ref;
99	      }
100	    } else {
101	      countryDocumentId = existing?.country?.documentId ?? null;
102	    }
103	
104	    let others: ExistingKey[] = [];
105	    if (countryDocumentId) {
106	      // Draft and published versions share a documentId, so excluding it covers both.
107	      others = (await strapi.documents(UID).findMany({
108	        filters: { country: { documentId: countryDocumentId } },
109	        fields: ['key'],
110	        status: 'draft',
111	      })) as ExistingKey[];
112	    }
113	
114	    const message = checkFormFieldIntegrity({ key, countryDocumentId, selfDocumentId }, others);
115	    if (message) throw new errors.ValidationError(message);
116	    return next();
117	  });
118	}
119	
120	/** Resolves the effective country (payload, else stored) of a plan and applies the Plan rule. */
121	async function checkPlan<T>(
122	  strapi: Core.Strapi,
123	  context: { params?: unknown },
124	  next: () => T,
125	): Promise<T> {
126	  const params = (context.params ?? {}) as { documentId?: string; data?: Record<string, unknown> };
127	  const { present, ref } = readCountryPayload((params.data ?? {}).country);
128	  let countryDocumentId: string | null = null;
129	  if (present) {
130	    if (typeof ref === 'number') {
131	      const found = (await strapi.db.query('api::country.country').findOne({ where: { id: ref } })) as {
132	        documentId: string;
133	      } | null;
134	      countryDocumentId = found?.documentId ?? null;
135	    } else {
136	      countryDocumentId = ref;
137	    }
138	  } else if (params.documentId) {
139	    const existing = (await strapi.documents(PLAN_UID).findOne({
140	      documentId: params.documentId,
141	      populate: { country: { fields: ['documentId'] } },
142	      status: 'draft',
143	    })) as { country?: { documentId: string } | null } | null;
144	    countryDocumentId = existing?.country?.documentId ?? null;
145	  }
146	  const message = checkPlanIntegrity({ countryDocumentId });
147	  if (message) throw new errors.ValidationError(message);
148	  return next();
149	}
