1	import { describe, expect, it } from 'vitest';
2	import { checkFormFieldIntegrity, checkPlanIntegrity, readCountryPayload } from './country-integrity';
3	
4	describe('US-01 · Edge Cases form field integrity', () => {
5	  const existing = [
6	    { documentId: 'a1', key: 'plate' },
7	    { documentId: 'a2', key: 'email' },
8	  ];
9	
10	  it('rejects a field without country', () => {
11	    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: null }, [])).toBe('El campo debe tener un país.');
12	  });
13	
14	  it('rejects a duplicate key in the same country', () => {
15	    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'co', selfDocumentId: 'new' }, existing)).toBe(
16	      'Ya existe un campo con la clave «plate» para este país.',
17	    );
18	  });
19	
20	  it('allows the same key in another country', () => {
21	    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'cl' }, [])).toBeNull();
22	  });
23	
24	  it('allows an update that keeps its own key', () => {
25	    expect(
26	      checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'co', selfDocumentId: 'a1' }, existing),
27	    ).toBeNull();
28	  });
29	
30	  it('allows a valid new field', () => {
31	    expect(checkFormFieldIntegrity({ key: 'city', countryDocumentId: 'co' }, existing)).toBeNull();
32	  });
33	
34	  it('reads the relation payload shapes', () => {
35	    expect(readCountryPayload(undefined)).toEqual({ present: false, ref: null });
36	    expect(readCountryPayload('abc')).toEqual({ present: true, ref: 'abc' });
37	    expect(readCountryPayload({ connect: [{ documentId: 'abc' }] })).toEqual({ present: true, ref: 'abc' });
38	    expect(readCountryPayload({ set: ['abc'] })).toEqual({ present: true, ref: 'abc' });
39	    expect(readCountryPayload({ set: [] })).toEqual({ present: true, ref: null });
40	    expect(readCountryPayload({ connect: [], disconnect: [{ id: 1 }] })).toEqual({ present: true, ref: null });
41	    expect(readCountryPayload(3)).toEqual({ present: true, ref: 3 });
42	  });
43	});
44	
45	describe('US-01 · FR-001 admin edits keep the country (Gate 3 manual test)', () => {
46	  it('reads the untouched relation from the admin as no change, so editing another attribute is allowed', () => {
47	    expect(readCountryPayload({ connect: [], disconnect: [] })).toEqual({ present: false, ref: null });
48	    expect(readCountryPayload({ connect: [] })).toEqual({ present: false, ref: null });
49	  });
50	
51	  it('reads a country changed in the admin (disconnect old, connect new)', () => {
52	    expect(
53	      readCountryPayload({ connect: [{ id: 2, documentId: 'cl' }], disconnect: [{ id: 1, documentId: 'co' }] }),
54	    ).toEqual({ present: true, ref: 'cl' });
55	  });
56	});
57	
58	
59	describe('US-02 · FR-001 plan integrity (UT-09)', () => {
60	  // The effective country is the payload's when present, else the stored one (null on create).
61	  const effective = (payload: unknown, stored: string | null) => {
62	    const { present, ref } = readCountryPayload(payload);
63	    return present ? (ref === null ? null : String(ref)) : stored;
64	  };
65	
66	  it('rejects a plan without country on create, update and publish', () => {
67	    // create: nothing stored; update/publish: the payload clears the relation, or nothing is stored.
68	    const cases: Array<[unknown, string | null]> = [
69	      [undefined, null],
70	      [null, 'co'],
71	      [{ set: [] }, 'co'],
72	      [{ connect: [], disconnect: [{ id: 1 }] }, 'co'],
73	      [{ connect: [], disconnect: [] }, null],
74	    ];
75	    for (const [payload, stored] of cases) {
76	      expect(checkPlanIntegrity({ countryDocumentId: effective(payload, stored) })).toBe('El plan debe tener un país.');
77	    }
78	  });
79	
80	  it('accepts a save that leaves the country untouched, or sets one', () => {
81	    expect(checkPlanIntegrity({ countryDocumentId: effective({ connect: [], disconnect: [] }, 'co') })).toBeNull();
82	    expect(checkPlanIntegrity({ countryDocumentId: effective({ connect: [{ documentId: 'cl' }] }, null) })).toBeNull();
83	  });
84	});
